struct RemoteProfileEditor {
    draft: RemoteDriveProfile,
    field: RemoteEditorField,
}

#[derive(Clone, Debug)]
struct BlockedRemoteDisconnect {
    id: String,
    pending_uploads: u64,
    errored_files: u64,
}

#[derive(Clone, Debug)]
struct TextPreviewUiState {
    wrap_override: Option<bool>,
    find: String,
    find_match: usize,
    unwrapped_scroll: UniformListScrollHandle,
    wrapped_list: ListState,
}

impl Default for TextPreviewUiState {
    fn default() -> Self {
        Self {
            wrap_override: None,
            find: String::new(),
            find_match: 0,
            unwrapped_scroll: UniformListScrollHandle::new(),
            wrapped_list: ListState::new(0, ListAlignment::Top, px(400.0)),
        }
    }
}

impl TextPreviewUiState {
    fn reset(&mut self) {
        self.wrap_override = None;
        self.find.clear();
        self.find_match = 0;
        self.unwrapped_scroll
            .0
            .borrow()
            .base_handle
            .set_offset(gpui::point(px(0.0), px(0.0)));
        self.wrapped_list.reset(0);
    }
}

