    fn refresh_video_frame(&mut self) {
        if let Ok(status) = self.services.video.status() {
            self.video_status = Some(status);
        }
        if let Ok(Some(frame)) = self.services.video.take_frame()
            && self.video_frame_position_ms != Some(frame.position_ms)
            && let Some(rendered) = render_video_frame(&frame)
        {
            self.video_frame_position_ms = Some(frame.position_ms);
            self.video_frame = Some(rendered);
        }
    }

    fn start_video_status_poll(&mut self, generation: u64, cx: &mut Context<Self>) {
        let executor = cx.background_executor().clone();
        self.video_tick_task = Some(cx.spawn(async move |this, cx| {
            loop {
                executor.timer(Duration::from_millis(66)).await;
                let keep_polling = this
                    .update(cx, |view, cx| {
                        if view.preview_generation != generation
                            || !matches!(
                                view.preview_state,
                                PreviewState::Ready {
                                    content: PreviewContent::Video,
                                    ..
                                }
                            )
                        {
                            return false;
                        }
                        let previous_position = view.video_frame_position_ms;
                        let previous_playing = view
                            .video_status
                            .as_ref()
                            .is_some_and(|status| status.playing);
                        view.refresh_video_frame();
                        let playing = view
                            .video_status
                            .as_ref()
                            .is_some_and(|status| status.playing);
                        if previous_position != view.video_frame_position_ms
                            || previous_playing != playing
                            || playing
                        {
                            cx.notify();
                        }
                        true
                    })
                    .unwrap_or(false);
                if !keep_polling {
                    break;
                }
            }
        }));
    }

    fn run_video_control(
        &mut self,
        task: BlockingTask<VideoStatus>,
        action: &'static str,
        cx: &mut Context<Self>,
    ) {
        let generation = self.preview_generation;
        self.preview_task = Some(cx.spawn(async move |this, cx| {
            let result = task.await;
            let _ = this.update(cx, |view, cx| {
                if view.preview_generation != generation
                    || !matches!(
                        view.preview_state,
                        PreviewState::Ready {
                            content: PreviewContent::Video,
                            ..
                        }
                    )
                {
                    return;
                }
                match result {
                    Ok(status) => {
                        view.video_status = Some(status);
                        view.refresh_video_frame();
                    }
                    Err(error) => {
                        view.status_message = Some(format!("Unable to {action} video: {error}"));
                    }
                }
                cx.notify();
            });
        }));
    }

