    fn remove_custom_field(&mut self, name: &str, cx: &mut Context<Self>) {
        let Some(editor) = &self.custom_fields_editor else {
            return;
        };
        if editor.pending || !editor.fields.contains_key(name) {
            return;
        }
        self.persist_custom_fields(
            editor.fields_without(name),
            format!("Removed custom field {name}"),
            cx,
        );
    }

    fn request_remove_custom_field(&mut self, name: &str, cx: &mut Context<Self>) {
        let Some(editor) = &self.custom_fields_editor else {
            return;
        };
        if editor.pending || !editor.fields.contains_key(name) {
            return;
        }
        self.request_settings_confirmation(
            SettingsConfirmation::RemoveCustomField(name.to_string()),
            cx,
        );
    }

    fn persist_custom_fields(
        &mut self,
        fields: HashMap<String, serde_json::Value>,
        success_message: String,
        cx: &mut Context<Self>,
    ) {
        let Some(editor) = &mut self.custom_fields_editor else {
            return;
        };
        if editor.pending {
            self.show_toast(
                "Wait for the current metadata save to finish",
                ToastKind::Warning,
                cx,
            );
            return;
        }
        let path = editor.path.clone();
        let Some(parent) = path.parent().map(Path::to_path_buf) else {
            self.show_toast(
                "Cannot save metadata for a filesystem root",
                ToastKind::Warning,
                cx,
            );
            return;
        };
        let Some(file_name) = path
            .file_name()
            .map(|name| name.to_string_lossy().into_owned())
        else {
            return;
        };
        editor.pending = true;
        let task = self
            .services
            .metadata
            .update_fields(parent, file_name, fields.clone());
        self.push_mutation_task(cx.spawn(async move |this, cx| {
            let result = task.await;
            let _ = this.update(cx, |view, cx| {
                let matches = view
                    .custom_fields_editor
                    .as_ref()
                    .is_some_and(|editor| editor.path == path);
                if matches {
                    match result {
                        Ok(()) => {
                            if let Some(editor) = &mut view.custom_fields_editor {
                                editor.apply_saved(fields);
                            }
                            view.show_toast(success_message, ToastKind::Success, cx);
                            view.refresh(cx);
                        }
                        Err(error) => {
                            if let Some(editor) = &mut view.custom_fields_editor {
                                editor.pending = false;
                            }
                            view.record_error("Custom fields save failed", error.to_string());
                            view.show_toast(
                                format!("Unable to save custom fields: {error}"),
                                ToastKind::Warning,
                                cx,
                            );
                        }
                    }
                }
                cx.notify();
            });
        }));
        cx.notify();
    }

