fn toolbar_button(
    id: impl Into<ElementId>,
    label: &str,
    color: gpui::Rgba,
) -> gpui::Stateful<gpui::Div> {
    toolbar_button_enabled(id, label, color, true)
}

fn toolbar_button_enabled(
    id: impl Into<ElementId>,
    label: &str,
    color: gpui::Rgba,
    enabled: bool,
) -> gpui::Stateful<gpui::Div> {
    div()
        .id(id)
        .role(Role::Button)
        .aria_label(label.to_string())
        .flex()
        .flex_shrink_0()
        .items_center()
        .justify_center()
        .px_3()
        .py_1()
        .rounded_sm()
        .border_1()
        .border_color(with_alpha(color, 0.0))
        .bg(color)
        .when(enabled, |button| {
            button
                .focusable()
                .tab_stop(true)
                .hover(move |button| button.bg(adaptive_hover(color)))
                .focus_visible(move |button| {
                    button
                        .bg(adaptive_hover(color))
                        .border_color(adaptive_hover(adaptive_hover(color)))
                })
                .active(|button| button.opacity(0.82))
                .cursor_pointer()
        })
        .when(!enabled, |button| button.opacity(0.58))
        .whitespace_nowrap()
        .text_sm()
        .child(label.to_string())
}

fn toolbar_icon(name: &'static str, size: f32, color: Rgba) -> impl IntoElement {
    svg()
        .path(format!("icons/{name}.svg"))
        .w(px(size))
        .h(px(size))
        .text_color(color)
}

fn compact_toolbar_button(
    id: &'static str,
    label: &str,
    icon: &'static str,
    palette: UiPalette,
    active: bool,
    enabled: bool,
) -> gpui::Stateful<gpui::Div> {
    compact_toolbar_button_with_tooltip(
        id,
        label,
        icon,
        palette,
        active,
        enabled,
        control_tooltip_text(label),
    )
}

fn compact_toolbar_button_with_tooltip(
    id: &'static str,
    label: &str,
    icon: &'static str,
    palette: UiPalette,
    active: bool,
    enabled: bool,
    tooltip: String,
) -> gpui::Stateful<gpui::Div> {
    let density_scale = if palette.density == Density::Compact {
        0.94
    } else {
        1.0
    };
    let size = 32.0 * palette.scale * density_scale;
    let foreground = if !enabled {
        palette.tertiary
    } else if active {
        palette.accent
    } else {
        palette.muted
    };
    div()
        .id(id)
        .debug_selector(move || id.to_string())
        .role(Role::Button)
        .aria_label(label.to_string())
        .flex()
        .flex_shrink_0()
        .items_center()
        .justify_center()
        .w(px(size))
        .h(px(size))
        .rounded(px(palette.radius))
        .border_1()
        .border_color(if active {
            palette.accent
        } else {
            with_alpha(palette.border, 0.0)
        })
        .bg(if active {
            palette.selected
        } else {
            with_alpha(palette.window, 0.0)
        })
        .when(enabled, |button| {
            button
                .focusable()
                .tab_stop(true)
                .focus_visible(move |button| button.bg(palette.hover).border_color(palette.accent))
                .hover(move |button| button.bg(palette.hover).border_color(palette.border))
                .active(|button| button.opacity(0.82))
                .cursor_pointer()
                .tooltip(move |_, cx| app_tooltip(tooltip.clone(), palette, cx))
        })
        .child(toolbar_icon(
            icon,
            palette.icon_size.clamp(14.0, 20.0),
            foreground,
        ))
}

fn toolbar_menu_item(
    id: &'static str,
    label: impl Into<String>,
    icon: &'static str,
    palette: UiPalette,
    active: bool,
) -> gpui::Stateful<gpui::Div> {
    let label = label.into();
    let foreground = if active { palette.accent } else { palette.text };
    div()
        .id(id)
        .debug_selector(move || id.to_string())
        .role(Role::Button)
        .aria_label(label.clone())
        .aria_selected(active)
        .focusable()
        .tab_stop(true)
        .flex()
        .items_center()
        .gap_2()
        .min_h(px(if palette.density == Density::Compact {
            30.0
        } else {
            34.0
        } * palette.scale))
        .px_2()
        .rounded(px(palette.radius))
        .border_1()
        .border_color(with_alpha(palette.border, 0.0))
        .bg(if active {
            palette.selected
        } else {
            with_alpha(palette.surface, 0.0)
        })
        .hover(move |row| row.bg(palette.hover))
        .focus_visible(move |row| row.bg(palette.hover).border_color(palette.accent))
        .active(|row| row.opacity(0.82))
        .cursor_pointer()
        .text_sm()
        .text_color(foreground)
        .child(
            div()
                .flex()
                .items_center()
                .justify_center()
                .w(px(20.0))
                .child(toolbar_icon(
                    icon,
                    palette.icon_size.clamp(13.0, 18.0),
                    foreground,
                )),
        )
        .child(div().flex_1().min_w_0().child(label))
}

