fn sort_label(browser: &BrowserState, key: &SortKey) -> String {
    if browser.sort_key() == *key {
        format!("{} {}", key.label(), browser.sort_direction().indicator())
    } else {
        let label = key.label();
        let mut characters = label.chars();
        characters.next().map_or_else(String::new, |first| {
            first.to_uppercase().collect::<String>() + characters.as_str()
        })
    }
}

fn list_custom_column_width(viewport_width: f32, column_count: usize) -> f32 {
    if column_count == 0 {
        return 0.0;
    }
    const BUILT_IN_AND_NAME_ALLOWANCE: f32 = 420.0; // 180 px Name + 110 px Size + 130 px Modified
    ((viewport_width - BUILT_IN_AND_NAME_ALLOWANCE) / column_count as f32).clamp(48.0, 160.0)
}

fn list_builtin_column_widths(custom_column_count: usize) -> (f32, f32) {
    if custom_column_count == 0 {
        (120.0, 140.0)
    } else {
        (110.0, 130.0)
    }
}

fn format_size(bytes: u64) -> String {
    const UNITS: [&str; 5] = ["B", "KB", "MB", "GB", "TB"];
    let mut value = bytes as f64;
    let mut unit = 0;
    while value >= 1024.0 && unit < UNITS.len() - 1 {
        value /= 1024.0;
        unit += 1;
    }
    if unit == 0 {
        format!("{bytes} B")
    } else {
        format!("{value:.1} {}", UNITS[unit])
    }
}

fn format_preview_size(bytes: u64) -> String {
    if bytes == 0 {
        return "0 Bytes".to_string();
    }
    const UNITS: [&str; 5] = ["Bytes", "KB", "MB", "GB", "TB"];
    let unit = ((bytes as f64).ln() / 1024_f64.ln()).floor() as usize;
    let unit = unit.min(UNITS.len() - 1);
    let value = bytes as f64 / 1024_f64.powi(unit as i32);
    if unit == 0 || value >= 10.0 {
        format!("{value:.0} {}", UNITS[unit])
    } else {
        format!("{value:.1} {}", UNITS[unit])
    }
}

